<?php $page_title='Klaim usaha';$this->load->view('staff/_layout_start',compact('user','page_title')); ?>
<section class="staff-hero"><div><span class="staff-kicker">KEPEMILIKAN</span><h1>Peninjauan klaim usaha</h1><p>Bandingkan bukti, profil registri, dan pemilik tercatat sebelum memberikan akses.</p></div></section>
<?php if ($this->input->get('tersimpan')): ?><div class="alert alert-success">Keputusan berhasil disimpan.</div><?php endif; ?>
<section class="staff-panel"><form method="get" class="staff-list-filter"><label>Cari<input class="form-control" type="search" name="q" maxlength="80" value="<?= html_escape($search) ?>" placeholder="Usaha atau pengaju"></label><label>Status<select class="form-select" name="status"><?php foreach(array('submitted'=>'Menunggu','approved'=>'Disetujui','rejected'=>'Ditolak') as $value=>$label): ?><option value="<?= $value ?>" <?= $status===$value?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label><?php $this->load->view('staff/_list_size',array('per_page'=>$per_page)); ?><button type="submit">Terapkan</button></form><p class="staff-list-count"><?= number_format($total,0,',','.') ?> pengajuan</p>
<?php if (!$rows): ?><p>Belum ada pengajuan pada status ini.</p><?php endif; ?>
<?php foreach($rows as $row): ?><article class="staff-panel"><h3><?= html_escape($row['business_name']) ?></h3><p>Pengaju: <?= html_escape($row['applicant_name'].' · '.$row['email']) ?><br>Pemilik tercatat: <?= html_escape($row['owner_name']?:'Belum tercatat') ?><br>Diajukan: <?= html_escape($row['created_at']) ?></p><p><?= nl2br(html_escape($row['reason'])) ?></p><p><a href="<?= site_url('pengelola/registri/'.$row['business_id']) ?>">Periksa registri</a> · <a href="<?= site_url('pengelola/klaim-usaha/'.$row['id'].'/bukti') ?>">Unduh bukti</a></p><?php if ($row['decision_note']): ?><p>Keputusan: <?= html_escape($row['decision_note']) ?></p><?php endif; ?><?php if ($row['status']==='submitted'): ?><form method="post" action="<?= site_url('pengelola/klaim-usaha/'.$row['id'].'/putusan') ?>"><input type="hidden" name="<?= $this->security->get_csrf_token_name() ?>" value="<?= $this->security->get_csrf_hash() ?>"><label class="form-label">Dasar keputusan<textarea class="form-control" name="decision_note" rows="2" minlength="20" maxlength="500" required></textarea></label><label class="form-check"><input class="form-check-input" type="checkbox" name="evidence_checked" value="1"><span class="form-check-label">Saya telah memeriksa bukti dan hubungan pemilik.</span></label><button class="btn btn-primary" type="submit" name="decision" value="approved">Setujui klaim</button> <button class="btn btn-outline-danger" type="submit" name="decision" value="rejected">Tolak</button></form><?php endif; ?></article><?php endforeach; ?>
<?php $this->load->view('staff/_pagination',array('base'=>site_url('pengelola/klaim-usaha'),'params'=>array('q'=>$search,'status'=>$status,'per_page'=>$per_page),'page'=>$page,'pages'=>$pages)); ?></section>
<?php $this->load->view('staff/_layout_end'); ?>
